const items = $input.all();

return items.map((item) => {
  const preguntaOriginal = (item.json.pregunta_usuario || "").toString().trim();

  const preguntaSinTildes = preguntaOriginal
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

  const preguntaNormalizada = preguntaSinTildes
    .toLowerCase()
    .replace(/[¿?¡!.,;:()[\]{}"'`´]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  return {
    json: {
      ...item.json,
      pregunta_original: preguntaOriginal,
      pregunta_normalizada: preguntaNormalizada,
      pregunta_valida: preguntaNormalizada.length > 0,
      longitud_pregunta: preguntaOriginal.length
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const pregunta = (item.json.pregunta_normalizada || "").toString();

  let tipoSolicitud = "documental";
  let confianza = "media";
  let motivo = "La pregunta parece relacionada con información general del hotel.";

  const contiene = (palabras) => palabras.some((p) => pregunta.includes(p));

  const pideCredenciales =
    (pregunta.includes("contrasena") ||
      pregunta.includes("password") ||
      pregunta.includes("clave") ||
      pregunta.includes("credencial") ||
      pregunta.includes("token") ||
      pregunta.includes("api key")) &&
    (pregunta.includes("administrador") ||
      pregunta.includes("admin") ||
      pregunta.includes("sistema") ||
      pregunta.includes("base de datos") ||
      pregunta.includes("interna") ||
      pregunta.includes("privada"));

  const pideDatosSensibles =
    pregunta.includes("datos privados") ||
    pregunta.includes("datos personales") ||
    pregunta.includes("numero de cuenta") ||
    pregunta.includes("cuenta bancaria interna") ||
    pregunta.includes("salario") ||
    pregunta.includes("cedula") ||
    pregunta.includes("telefono privado");

  const pideAccionPeligrosa =
    pregunta.includes("hackear") ||
    pregunta.includes("borrar base de datos") ||
    pregunta.includes("eliminar base de datos") ||
    pregunta.includes("modificar base de datos") ||
    pregunta.includes("romper seguridad") ||
    pregunta.includes("acceso no autorizado");

  const palabrasAnalitica = [
    "dataset",
    "datos historicos",
    "reservas historicas",
    "tasa de cancelacion",
    "porcentaje de cancelacion",
    "cancelaciones",
    "adr",
    "precio promedio",
    "lead time",
    "segmento de mercado",
    "mes con mas reservas",
    "hotel con mas reservas",
    "city hotel",
    "resort hotel",
    "estadistica",
    "estadisticas",
    "analisis",
    "promedio",
    "porcentaje",
    "metricas",
    "datos de reservas"
  ];

  const palabrasReserva = [
    "quiero reservar",
    "hacer una reserva",
    "necesito reservar",
    "reservar una habitacion",
    "reservar habitacion",
    "solicitar una reserva",
    "habitacion doble para",
    "habitacion sencilla para",
    "habitacion familiar para",
    "habitacion triple para",
    "suite para",
    "me quiero hospedar",
    "quiero hospedarme",
    "quiero una habitacion",
    "necesito una habitacion"
  ];

  const palabrasDocumental = [
    "politica",
    "cancelacion",
    "check in",
    "check out",
    "habitaciones",
    "mascotas",
    "desayuno",
    "parqueadero",
    "wifi",
    "internet",
    "recepcion",
    "servicios",
    "menores",
    "familias",
    "no show",
    "pagos",
    "normas",
    "ruido",
    "fumar",
    "equipaje",
    "lavanderia",
    "horario",
    "tarifa",
    "reserva"
  ];

  if (!item.json.pregunta_valida) {
    tipoSolicitud = "fuera_alcance";
    confianza = "alta";
    motivo = "La pregunta está vacía o no contiene información útil.";
  } else if (pideCredenciales || pideDatosSensibles || pideAccionPeligrosa) {
    tipoSolicitud = "fuera_alcance";
    confianza = "alta";
    motivo = "La pregunta solicita información sensible, privada o no permitida.";
  } else if (contiene(palabrasAnalitica)) {
    tipoSolicitud = "analitica_dataset";
    confianza = "alta";
    motivo = "La pregunta solicita análisis o métricas del dataset hotelero.";
  } else if (contiene(palabrasReserva)) {
    tipoSolicitud = "reserva_simulada";
    confianza = "alta";
    motivo = "La pregunta parece una intención de reserva simulada.";
  } else if (contiene(palabrasDocumental)) {
    tipoSolicitud = "documental";
    confianza = "alta";
    motivo = "La pregunta se relaciona con políticas, servicios o información del hotel.";
  }

  return {
    json: {
      ...item.json,
      tipo_solicitud: tipoSolicitud,
      confianza_clasificacion: confianza,
      motivo_clasificacion: motivo
    }
  };
});

