const items = $input.all();

return items.map((item) => {
  const faltantes = item.json.datos_faltantes || [];

  return {
    json: {
      tipo_solicitud: "reserva_simulada",
      pregunta_usuario: item.json.pregunta_usuario || item.json.pregunta_original || "",
      nombre_hotel: item.json.nombre_hotel || "Hotel El Claustro de San Francisco",
      tipo_habitacion: item.json.tipo_habitacion,
      numero_noches: item.json.numero_noches,
      numero_personas: item.json.numero_personas,
      fecha_entrada: item.json.fecha_entrada,
      datos_faltantes: faltantes,
      respuesta_final: `Para simular la reserva necesito que me indiques: ${faltantes.join(", ")}.`,
      estado: "reserva_pendiente_datos",
      fuente: "Reglas internas de simulación de reserva",
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();

function formatoNumero(valor) {
  if (valor === null || valor === undefined || valor === "") return "no disponible";
  const numero = Number(valor);
  if (Number.isNaN(numero)) return valor.toString();
  return numero.toLocaleString("es-CO");
}

function formatoDecimal(valor) {
  if (valor === null || valor === undefined || valor === "") return "no disponible";
  const numero = Number(valor);
  if (Number.isNaN(numero)) return valor.toString();
  return numero.toLocaleString("es-CO", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

return items.map((item) => {
  const pregunta = $("Code - Clasificar Intención").item.json.pregunta_normalizada || "";
  const preguntaUsuario = $("Edit Fields").item.json.pregunta_usuario || "";
  const nombreHotel = $("Edit Fields").item.json.nombre_hotel || "Hotel El Claustro de San Francisco";
  const m = item.json;

  let respuesta = "";

  if (pregunta.includes("tasa de cancelacion") || pregunta.includes("porcentaje de cancelacion") || pregunta.includes("cancelaciones")) {
    respuesta =
      `Según el dataset histórico, la tasa global de cancelación es de ${formatoDecimal(m.tasa_cancelacion_porcentaje)}%. ` +
      `Para City Hotel es de ${formatoDecimal(m.cancelacion_city_hotel)}% y para Resort Hotel es de ${formatoDecimal(m.cancelacion_resort_hotel)}%.`;
  } else if (pregunta.includes("adr") || pregunta.includes("precio promedio")) {
    respuesta =
      `Según el dataset histórico, el ADR promedio registrado es de ${formatoDecimal(m.adr_promedio)}.`;
  } else if (pregunta.includes("lead time") || pregunta.includes("anticipacion")) {
    respuesta =
      `Según el dataset histórico, el lead time promedio es de ${formatoDecimal(m.lead_time_promedio)} días.`;
  } else if (pregunta.includes("mes") && pregunta.includes("reservas")) {
    respuesta =
      `Según el dataset histórico, el mes con más reservas es ${m.mes_mas_reservas}.`;
  } else if (pregunta.includes("segmento")) {
    respuesta =
      `Según el dataset histórico, el segmento de mercado más frecuente es ${m.segmento_mas_frecuente}.`;
  } else if (pregunta.includes("city hotel") || pregunta.includes("resort hotel") || pregunta.includes("hotel con mas reservas")) {
    respuesta =
      `Según el dataset histórico, City Hotel registra ${formatoNumero(m.reservas_city_hotel)} reservas y Resort Hotel registra ${formatoNumero(m.reservas_resort_hotel)} reservas.`;
  } else {
    respuesta =
      `Resumen analítico del dataset: total de reservas ${formatoNumero(m.total_reservas)}, ` +
      `tasa de cancelación ${formatoDecimal(m.tasa_cancelacion_porcentaje)}%, ` +
      `ADR promedio ${formatoDecimal(m.adr_promedio)}, ` +
      `lead time promedio ${formatoDecimal(m.lead_time_promedio)} días, ` +
      `mes con más reservas ${m.mes_mas_reservas} y segmento más frecuente ${m.segmento_mas_frecuente}.`;
  }

  return {
    json: {
      tipo_solicitud: "analitica_dataset",
      pregunta_usuario: preguntaUsuario,
      pregunta_normalizada: pregunta,
      nombre_hotel: nombreHotel,
      fuente: "Dataset hotel_bookings cargado en PostgreSQL",
      total_reservas: Number(m.total_reservas),
      tasa_cancelacion_porcentaje: Number(m.tasa_cancelacion_porcentaje),
      adr_promedio: Number(m.adr_promedio),
      lead_time_promedio: Number(m.lead_time_promedio),
      reservas_city_hotel: Number(m.reservas_city_hotel),
      reservas_resort_hotel: Number(m.reservas_resort_hotel),
      cancelacion_city_hotel: Number(m.cancelacion_city_hotel),
      cancelacion_resort_hotel: Number(m.cancelacion_resort_hotel),
      mes_mas_reservas: m.mes_mas_reservas,
      segmento_mas_frecuente: m.segmento_mas_frecuente,
      respuesta_final: respuesta,
      estado: "analitica_dataset_completada",
      timestamp: new Date().toISOString()
    }
  };
});
